using System.Buffers.Binary;
using System.Runtime.CompilerServices;
using System.Text;

namespace TreeSpitter;

/// <summary>
/// The keywords of a language, keyed by their length and their first 8 bytes as a <see cref="ulong"/>, like the
/// lookups generated by Parlot. tree-sitter lexes the word token (identifiers), then runs the keyword automaton from the
/// start of the token: when the keywords are a finite set of strings, looking up the bytes of the token gives the same
/// keyword without running the automaton. Generated parsers compile the same lookup to switches (see
/// <c>CodeGen/KnownBytesLookup</c>).
/// </summary>
internal sealed class KeywordTable
{
    /// <summary>The result of <see cref="Lookup"/> when the token isn't a keyword.</summary>
    public const int NotFound = -1;

    /// <summary>The result of <see cref="Lookup"/> when the keyword automaton must decide (a keyword that is a prefix of another).</summary>
    public const int UseAutomaton = -2;

    private const int MaxKeywords = 4096;

    /// <summary>The longest keyword.</summary>
    public const int MaxLength = 64;

    private readonly ulong[] _heads;
    private readonly int[] _lengths;
    private readonly byte[]?[] _tails;
    private readonly int[] _values;
    private readonly int _shift;
    private readonly int _maxLength;

    private KeywordTable(List<(byte[] Key, int Value)> entries)
    {
        Entries = entries;
        var bits = 4;
        while ((1 << bits) < entries.Count * 4)
        {
            bits++;
        }

        var size = 1 << bits;
        _shift = 64 - bits;
        _heads = new ulong[size];
        _lengths = new int[size];
        _tails = new byte[size][];
        _values = new int[size];
        foreach (var (key, value) in entries)
        {
            var head = Head(key, 0, key.Length);
            var index = Index(head, key.Length);
            while (_lengths[index] != 0)
            {
                index = (index + 1) & (size - 1);
            }

            _heads[index] = head;
            _lengths[index] = key.Length;
            _tails[index] = key.Length > 8 ? key.AsSpan(8).ToArray() : null;
            _values[index] = value;
            _maxLength = Math.Max(_maxLength, key.Length);
        }
    }

    /// <summary>The keywords (UTF-8) and their symbols, or <see cref="UseAutomaton"/>.</summary>
    public IReadOnlyList<(byte[] Key, int Value)> Entries { get; }

    /// <summary>The keyword symbol of a token, <see cref="NotFound"/> or <see cref="UseAutomaton"/>.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public int Lookup(ReadOnlySpan<byte> input, int start, int end)
    {
        var length = end - start;
        if ((uint)(length - 1) >= (uint)_maxLength)
        {
            return NotFound;
        }

        // Size + prefix: the first 8 bytes of the token as a ulong, the bytes after its end masked out
        ulong head;
        if (start + 8 <= input.Length)
        {
            head = BinaryPrimitives.ReadUInt64LittleEndian(input.Slice(start, 8));
            if (length < 8)
            {
                head &= (1UL << (length * 8)) - 1;
            }
        }
        else
        {
            head = Head(input, start, length);
        }

        var mask = _heads.Length - 1;
        var index = Index(head, length);
        while (true)
        {
            var entryLength = _lengths[index];
            if (entryLength == 0)
            {
                return NotFound;
            }

            if (entryLength == length && _heads[index] == head &&
                (length <= 8 || input.Slice(start + 8, length - 8).SequenceEqual(_tails[index])))
            {
                return _values[index];
            }

            index = (index + 1) & mask;
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Index(ulong head, int length) => (int)(((head ^ ((ulong)length << 59)) * 0x9E3779B97F4A7C15UL) >> _shift);

    /// <summary>The first 8 bytes of a key, little-endian, zero-padded.</summary>
    private static ulong Head(ReadOnlySpan<byte> bytes, int start, int length)
    {
        ulong head = 0;
        var count = Math.Min(length, 8);
        for (var i = 0; i < count; i++)
        {
            head |= (ulong)bytes[start + i] << (i * 8);
        }

        return head;
    }

    /// <summary>
    /// Builds the table of a keyword automaton, or returns null when it doesn't accept a small finite set of strings
    /// (patterns, case-insensitive keywords).
    /// </summary>
    public static KeywordTable? Create(LexAutomaton automaton)
    {
        if (automaton.StateCount == 0)
        {
            return null;
        }

        var accepted = new List<(string Text, int Symbol)>();
        var path = new StringBuilder();
        var onPath = new HashSet<int>();
        if (!Enumerate(automaton, 0, path, onPath, accepted, true) || accepted.Count == 0)
        {
            return null;
        }

        var texts = new HashSet<string>(accepted.Select(a => a.Text), StringComparer.Ordinal);
        var entries = new List<(byte[] Key, int Value)>();
        foreach (var (text, symbol) in accepted)
        {
            // A keyword which is a prefix of another one: the automaton reads past its end, let it decide
            var isPrefix = texts.Any(other => other.Length > text.Length && other.StartsWith(text, StringComparison.Ordinal));
            entries.Add((Encoding.UTF8.GetBytes(text), isPrefix ? UseAutomaton : symbol));
        }

        return entries.Any(e => e.Key.Length > MaxLength) ? null : new KeywordTable(entries);
    }

    private static bool Enumerate(LexAutomaton automaton, int state, StringBuilder path, HashSet<int> onPath, List<(string Text, int Symbol)> accepted, bool isStart)
    {
        if (accepted.Count > MaxKeywords || path.Length > MaxLength || !onPath.Add(state))
        {
            // Too many keywords, or a cycle: not a finite set of strings
            return false;
        }

        if (!isStart && automaton.Accept[state] >= 0)
        {
            accepted.Add((path.ToString(), automaton.Accept[state]));
        }

        for (var i = automaton.TransitionStart[state]; i < automaton.TransitionStart[state + 1]; i++)
        {
            var target = automaton.RangeTarget[i];
            if ((target & LexAutomaton.SkipFlag) != 0)
            {
                // The separators before the keywords: the token starts after them
                continue;
            }

            var low = automaton.RangeStart[i];
            var high = automaton.RangeEnd[i];
            if (high - low > 4 || low < 0 || low is >= 0xD800 and <= 0xDFFF || high > 0x10FFFF)
            {
                return false;
            }

            for (var c = low; c <= high; c++)
            {
                var length = path.Length;
                path.Append(char.ConvertFromUtf32(c));
                if (!Enumerate(automaton, target, path, onPath, accepted, false))
                {
                    return false;
                }

                path.Length = length;
            }
        }

        onPath.Remove(state);
        return true;
    }
}
